#!/usr/bin/env node

/**
 * Timar AI MCP Server - STDIO Transport Entry Point
 *
 * This script starts the MCP server using stdio transport.
 * Configuration is loaded from the config file generated by setup wizard.
 *
 * If no configuration is found, it will guide the user to run setup.
 *
 * Usage:
 *   node scripts/start-stdio-server.mjs
 *
 * First time? Run setup first:
 *   node scripts/setup.mjs
 */

import { join, resolve } from "node:path";
import { loadRuntimeSource, validateRuntimeStartup, loadLanguagePreference } from "../src/config/load-runtime-source.ts";
import { createServerRuntime } from "../src/server/index.ts";
import { startStdioMcpServer } from "../src/server/mcp-protocol.ts";

const CYAN = "\x1b[36m";
const GREEN = "\x1b[32m";
const YELLOW = "\x1b[33m";
const BOLD = "\x1b[1m";
const DIM = "\x1b[2m";
const RESET = "\x1b[0m";

// i18n for startup messages
const startupI18n = {
  "zh-CN": {
    noConfig: "⚠️  未检测到配置",
    firstTime: "看起来这是你第一次使用 Timar AI MCP 服务器。",
    runSetup: "运行以下命令开始交互式配置：",
    setupSteps: [
      "1. 选择语言（简体中文 / 繁體中文 / English）",
      "2. 选择环境（Sandbox / Production）",
      "3. 填写 API 域名、API Key 和 Secret Key",
      "4. 自动保存配置并生成 AI 客户端接入代码",
    ],
    validateFailed: "⚠️  配置验证失败",
    rerunSetup: "请重新运行配置向导：",
    started: "✅ Timar AI MCP 服务器已启动",
    protocolVersion: "协议版本",
    defaultEnv: "默认环境",
    environments: "已配置环境",
    tools: "可用工具",
  },
  "zh-TW": {
    noConfig: "⚠️  未偵測到設定",
    firstTime: "看起來這是你第一次使用 Timar AI MCP 伺服器。",
    runSetup: "執行以下命令開始互動式設定：",
    setupSteps: [
      "1. 選擇語言（简体中文 / 繁體中文 / English）",
      "2. 選擇環境（Sandbox / Production）",
      "3. 填寫 API 網域、API Key 和 Secret Key",
      "4. 自動儲存設定並產生 AI 用戶端接入代碼",
    ],
    validateFailed: "⚠️  設定驗證失敗",
    rerunSetup: "請重新執行設定精靈：",
    started: "✅ Timar AI MCP 伺服器已啟動",
    protocolVersion: "協定版本",
    defaultEnv: "預設環境",
    environments: "已設定環境",
    tools: "可用工具",
  },
  "en": {
    noConfig: "⚠️  No configuration found",
    firstTime: "It looks like this is your first time using Timar AI MCP Server.",
    runSetup: "Run the setup wizard to get started:",
    setupSteps: [
      "1. Choose language (简体中文 / 繁體中文 / English)",
      "2. Choose environment (Sandbox / Production)",
      "3. Enter API domain, API Key, and Secret Key",
      "4. Auto-save config and generate AI client integration code",
    ],
    validateFailed: "⚠️  Configuration validation failed",
    rerunSetup: "Please re-run the setup wizard:",
    started: "✅ Timar AI MCP Server started",
    protocolVersion: "Protocol Version",
    defaultEnv: "Default Environment",
    environments: "Environments",
    tools: "Tools",
  },
};

// Try to detect language for error messages
function detectLang() {
  // 1. Try loading from existing config
  try {
    const lang = loadLanguagePreference();
    if (startupI18n[lang]) return lang;
  } catch {
    // ignore
  }

  // 2. Fallback: detect from system locale
  const locale = (process.env.LANG || process.env.LC_ALL || process.env.LC_MESSAGES || "").toLowerCase();
  if (locale.includes("zh_tw") || locale.includes("zh-hant") || locale.includes("traditional")) return "zh-TW";
  if (locale.includes("zh_cn") || locale.includes("zh-hans") || locale.includes("simplified") || locale.includes("zh")) return "zh-CN";

  return "en";
}

const lang = detectLang();
const t = startupI18n[lang];

// Load configuration
let config;

try {
  config = loadRuntimeSource();
} catch (error) {
  // No config found - guide user to setup
  console.error("");
  console.error(`${YELLOW}${BOLD}  ${t.noConfig}${RESET}`);
  console.error("");
  console.error(`  ${t.firstTime}`);
  console.error(`  ${t.runSetup}`);
  console.error("");
  console.error(`  ${GREEN}${BOLD}node scripts/setup.mjs${RESET}`);
  console.error("");
  console.error(`  ${t.setupSteps.map((s) => `${DIM}${s}${RESET}`).join("\n  ")}`);
  console.error("");

  process.exit(1);
}

// Validate configuration
try {
  validateRuntimeStartup(config);
} catch (error) {
  console.error("");
  console.error(`${YELLOW}${BOLD}  ${t.validateFailed}${RESET}`);
  console.error("");
  console.error(error instanceof Error ? error.message : String(error));
  console.error("");
  console.error(`  ${t.rerunSetup}${GREEN}${BOLD}node scripts/setup.mjs${RESET}`);
  console.error("");
  process.exit(1);
}

// Create server runtime
const runtime = createServerRuntime(config);

// Log startup info (to stderr so it doesn't interfere with MCP protocol on stdout)
console.error("");
console.error(`${GREEN}${BOLD}  ${t.started}${RESET}`);
console.error("");
console.error(`   ${t.protocolVersion}: 2025-11-25`);
console.error(`   ${t.defaultEnv}: ${config.defaultEnvironment}`);
console.error(`   ${t.environments}: ${Object.keys(config.environments).join(", ")}`);
console.error(`   ${t.tools}: ${runtime.diagnostics.toolNames.join(", ")}`);
console.error("");

// Start STDIO server
startStdioMcpServer(runtime);
